#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn language_codes_round_trip() {
        for language in Language::ALL {
            assert_eq!(Language::from_code(language.code()), language);
        }
        assert_eq!(Language::from_code("unknown"), Language::Portuguese);
    }
    #[test]
    fn translations_preserve_paths_and_cover_all_languages() {
        for (choice, expected) in Language::ALL.into_iter().zip([
            "Escolher pasta…",
            "Choose folder…",
            "Elegir carpeta…",
            "フォルダを選択…",
        ]) {
            assert_eq!(text_for("Escolher pasta…", choice), expected);
            assert_eq!(
                text_for("/Volumes/Meu HD/日本語.mov", choice),
                "/Volumes/Meu HD/日本語.mov"
            );
        }
    }
    #[test]
    fn catalog_is_complete() {
        for line in include_str!("i18n.tsv").lines().skip(1) {
            let fields: Vec<_> = line.split('\t').collect();
            assert_eq!(fields.len(), 4);
            assert!(fields.iter().all(|s| !s.trim().is_empty()));
        }
    }
}
